const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
    terminal: false
});

rl.on('line', (line) => {
    const n = parseInt(line.trim(), 10);
    if (isNaN(n)) return;
    if (n % 2 !== 0) {
        console.log("Ehab");
    } else {
        console.log("Mahmoud");
    }
});

